program.compute:
options = read('/input/options')
artifact = read('/output/selection')
if valid(artifact):
    result = artifact
else:
    result = []
    for k in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(options, k):
            ids = [item['id'] for item in group]
            if valid(ids):
                result = ids
                break
        if result:
            break

program.effects:
if not valid(read('/output/selection')):
    write('/output/selection', result)
if receipt('report') != 'success':
    if receipt('report') == 'unknown':
        status('report')
    if receipt('report') == 'unattempted' or receipt('report') == 'failure':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

